import{_ as a,o as s,c as i,a6 as t}from"./chunks/framework.CKIbuWFA.js";const k=JSON.parse('{"title":"診断と安全な証拠収集","description":"","frontmatter":{"title":"診断と安全な証拠収集","docId":"developer.diagnostics","translationKey":"developer.diagnostics","locale":"ja","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"bd492eda2007394d29d152e20ec0dba70614f06e6d29b75a3b741ed6b23f11b4","translationRevision":"4c8b2b8ff62f3ab4bde2217b350936d3ef395dddfa74803ddacdc3b9edf62e02","order":130},"headers":[],"relativePath":"ja/developer/diagnostics.md","filePath":"ja/developer/diagnostics.md","lastUpdated":1794611623000}'),n={name:"ja/developer/diagnostics.md"};function d(r,e,o,l,h,c){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="diagnostics-and-safe-evidence" tabindex="-1">診断と安全な証拠収集 <a class="header-anchor" href="#diagnostics-and-safe-evidence" aria-label="Permalink to &quot;診断と安全な証拠収集 {#diagnostics-and-safe-evidence}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目的と前提条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目的と前提条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>アカウントの秘密を残さず、診断と復旧を混同せずに、原因特定に十分な証拠を集めます。非公開テストホストを使い、選択された<a href="./transports.html">通信経路</a> を把握します。アプリはセッション用収集器を1つ設置し、状態部品は描画中に記録を追加せず、そこへ移動します。</p><h2 id="inspect-a-failure" tabindex="-1">失敗を調べる <a class="header-anchor" href="#inspect-a-failure" aria-label="Permalink to &quot;失敗を調べる {#inspect-a-failure}&quot;">​</a></h2><ol><li>失敗した接続、プラグイン、同期、更新の状態操作を開きます。デスクトップのログ操作はホバーと同様にキーボードフォーカスでも表示されます。</li><li>発生元、重大度、文字列で絞り、選択項目の文脈と繰り返し数を確認します。</li><li>説明に役立つ選択項目か絞り込んだ項目をコピーします。書き出しは共有前に確認します。</li><li>ネイティブの健全性とフロントエンドの観測を比べます。</li></ol><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/debug/tiktools</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> info</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/debug/tiktools</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> health</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/debug/tiktools</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span></code></pre></div><p>切断中の LIVE 検査は省略される場合があります。コンパイル済み機能は実行時の利用可否を証明しません。デスクトップでは非モーダルのパネル、狭い画面では戻り先付きの <code>/debug</code> を使います。ネイティブのテキスト保存は <code>system.saveFile</code>、ブラウザーはローカルダウンロードです。</p><h2 id="understand-retention" tabindex="-1">保持の仕組み <a class="header-anchor" href="#understand-retention" aria-label="Permalink to &quot;保持の仕組み {#understand-retention}&quot;">​</a></h2><p><code>src/web/shared/diagnostics/log.ts</code> は履歴を2,000件、直列化 UTF-8 で2 MiB に制限します。同じ発生元・エンティティの連続イベントは5秒以内なら繰り返し数にまとめます。認識できる認証情報や URL の秘密箇所は保持前に編集除去しますが、ラベルのない第三者の秘密は常に認識できるとは限りません。生の設定、Cookie、RPC パラメーター、HTTP 本文を収集器に追加しないでください。</p><h2 id="expected-result-and-status" tabindex="-1">期待される結果と提供状況 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;期待される結果と提供状況 {#expected-result-and-status}&quot;">​</a></h2><p>表示器は制限付きセッション履歴と文脈への移動を提供し、永続監査ログではありません。再読み込み・アンマウントでメモリーは消えます。履歴消去は接続エラーや原因を直しません。Cloud 要求 ID は安全な失敗情報の照合に役立ちますが、収集範囲は設置した収集器に従い、すべての登録・ネイティブエラーを必ず捕捉するわけではありません。</p><h2 id="verify-and-recover" tabindex="-1">検証と対処 <a class="header-anchor" href="#verify-and-recover" aria-label="Permalink to &quot;検証と対処 {#verify-and-recover}&quot;">​</a></h2><p><code>bun scripts/task.ts test web diagnostics</code> を実行し、<a href="https://github.com/nglmercer/TikTools-app/tree/remake/src/web/shared/diagnostics" target="_blank" rel="noreferrer">収集器ソース</a> を確認します。合成値で秘密除去、古い項目の排出、反復イベントを再現します。競合、結果不明コマンド、認証期限切れは担当の復旧フローに戻ります。診断コピーは証拠収集であり、操作の再試行や新しい信頼方針の承認ではありません。</p>`,13)])])}const u=a(n,[["render",d]]);export{k as __pageData,u as default};
